const data = $input.first().json;
const posts = data?.data?.children || [];
const topPosts = posts
  .filter(p => !p.data.stickied)
  .slice(0, 10)
  .map((p, i) => {
    const d = p.data;
    return `${i+1}. [Score: ${d.score}] ${d.title} (${d.num_comments} comments)`;
  })
  .join('\n');

return {
  json: {
    redditSummary: topPosts
  }
};

const redditData = $('Format Reddit Data').first().json.redditSummary || 'No Reddit data';

const hnRaw = $input.first().json;
const hnHits = hnRaw.hits || [];
const hnSummary = hnHits.slice(0, 10).map((h, i) => {
  return `${i+1}. [Points: ${h.points}] ${h.title} (${h.num_comments} comments) - ${h.url || 'https://news.ycombinator.com/item?id=' + h.objectID}`;
}).join('
');

return {
  json: {
    redditSummary: redditData,
    hnSummary: hnSummary,
    combinedPrompt: `REDDIT TOP POSTS (r/technology):
${redditData}

HACKER NEWS FRONT PAGE:
${hnSummary}

From the stories above, pick the SINGLE most interesting, viral tech/AI story that would make an engaging 45-second YouTube Short. Return in this format:

STORY_TITLE: [the headline]
KEY_FACTS:
- [fact 1]
- [fact 2]
- [fact 3]
- [fact 4]
WHY_TRENDING: [1-2 sentences on why this is hot news]
SOURCES:
- [source URL 1]
- [source URL 2]`
  }
};

const data = $input.first().json;

return {
  json: {
    rawStory: data.combinedPrompt,
    redditSummary: data.redditSummary,
    hnSummary: data.hnSummary,
    timestamp: new Date().toISOString()
  }
};

// Gemini response format: candidates[0].content.parts[0].text
const geminiResponse = $input.first().json;
let response = '';

try {
  response = geminiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Could not extract text from Gemini response: ' + JSON.stringify(geminiResponse).substring(0, 300));
}

let parsed;
try {
  parsed = JSON.parse(response);
} catch (e) {
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Could not parse script JSON from Gemini response: ' + response.substring(0, 200));
  }
}

if (!parsed.SCRIPT) throw new Error('Missing SCRIPT in response');
if (!parsed.TITLE) throw new Error('Missing TITLE in response');
if (!parsed.IMAGE_PROMPTS || !Array.isArray(parsed.IMAGE_PROMPTS)) throw new Error('Missing IMAGE_PROMPTS array');
if (parsed.IMAGE_PROMPTS.length < 4) throw new Error('Need at least 4 image prompts, got ' + parsed.IMAGE_PROMPTS.length);

const wordCount = parsed.SCRIPT.split(/\s+/).length;

return {
  json: {
    script: parsed.SCRIPT,
    title: parsed.TITLE,
    description: parsed.DESCRIPTION || '',
    tags: parsed.TAGS || [],
    imagePrompts: parsed.IMAGE_PROMPTS,
    wordCount: wordCount,
    timestamp: new Date().toISOString()
  }
};

const items = $input.all();
const imageBase64Array = [];

for (const item of items) {
  const candidates = item.json.candidates || [];
  let found = false;
  for (const candidate of candidates) {
    const parts = candidate.content?.parts || [];
    for (const part of parts) {
      if (part.inlineData && part.inlineData.mimeType?.startsWith('image/')) {
        imageBase64Array.push(part.inlineData.data);
        found = true;
        break;
      }
    }
    if (found) break;
  }
  if (!found) {
    throw new Error('No image data found in Gemini response for item: ' + JSON.stringify(item.json).substring(0, 200));
  }
}

return {
  json: {
    imageBase64Array: imageBase64Array,
    imageCount: imageBase64Array.length
  }
};

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Get image data from Collect All Images
const images = $('Collect All Images').first().json.imageBase64Array || [];
if (images.length === 0) throw new Error('No images found from Collect All Images');

// Get audio data from Gemini TTS response
const ttsResponse = $input.first().json;
let audioBase64 = '';
try {
  audioBase64 = ttsResponse.candidates[0].content.parts[0].inlineData.data;
} catch (e) {
  throw new Error('Could not extract audio from Gemini TTS response: ' + JSON.stringify(ttsResponse).substring(0, 300));
}

// Create temp directory
const tmpDir = '/tmp/n8n_video_' + Date.now();
fs.mkdirSync(tmpDir, { recursive: true });

try {
  // Write images to temp files
  const imgPaths = [];
  for (let i = 0; i < images.length; i++) {
    const imgPath = path.join(tmpDir, `img_${i}.png`);
    fs.writeFileSync(imgPath, Buffer.from(images[i], 'base64'));
    imgPaths.push(imgPath);
  }

  // Write audio PCM and convert to WAV (Gemini TTS: 24kHz, 16-bit, mono)
  const pcmPath = path.join(tmpDir, 'audio.pcm');
  const wavPath = path.join(tmpDir, 'audio.wav');
  fs.writeFileSync(pcmPath, Buffer.from(audioBase64, 'base64'));
  execSync(`ffmpeg -y -f s16le -ar 24000 -ac 1 -i "${pcmPath}" "${wavPath}"`, { timeout: 30000 });

  // Get audio duration
  const probeOutput = execSync(`ffprobe -v error -show_entries format=duration -of csv=p=0 "${wavPath}"`).toString().trim();
  const totalDuration = parseFloat(probeOutput) || 45;

  const numImages = images.length;
  const fadeDuration = 0.5;
  // Each image duration: total + overlaps / num images
  const imgDuration = (totalDuration + (numImages - 1) * fadeDuration) / numImages;
  const fps = 30;
  const frames = Math.ceil(imgDuration * fps);

  // Build FFmpeg inputs
  let inputArgs = '';
  for (let i = 0; i < numImages; i++) {
    inputArgs += ` -loop 1 -t ${imgDuration.toFixed(2)} -i "${imgPaths[i]}"`;
  }
  inputArgs += ` -i "${wavPath}"`;

  // Build filter: scale + Ken Burns zoom for each image
  const filterParts = [];
  for (let i = 0; i < numImages; i++) {
    const zoomIn = i % 2 === 0;
    const zoomExpr = zoomIn ? "min(zoom+0.0015,1.4)" : "if(eq(on,1),1.4,max(zoom-0.0015,1.0))";
    filterParts.push(
      `[${i}:v]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,` +
      `zoompan=z='${zoomExpr}':d=${frames}:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':` +
      `s=1080x1920:fps=${fps}[v${i}]`
    );
  }

  // Build xfade chain
  const xfadeParts = [];
  let lastLabel = 'v0';
  for (let i = 1; i < numImages; i++) {
    const offset = (imgDuration * i - fadeDuration * i).toFixed(2);
    const outLabel = i < numImages - 1 ? `t${i}` : 'vout';
    xfadeParts.push(`[${lastLabel}][v${i}]xfade=transition=fade:duration=${fadeDuration}:offset=${offset}[${outLabel}]`);
    lastLabel = outLabel;
  }

  const fullFilter = filterParts.join('; ') + '; ' + xfadeParts.join('; ');
  const outputPath = path.join(tmpDir, 'output.mp4');

  const cmd = `ffmpeg${inputArgs} -filter_complex "${fullFilter}" -map "[vout]" -map ${numImages}:a ` +
    `-c:v libx264 -preset fast -crf 23 -pix_fmt yuv420p -c:a aac -b:a 128k -shortest -y "${outputPath}"`;

  execSync(cmd, { maxBuffer: 200 * 1024 * 1024, timeout: 300000 });

  // Read output video and return as binary
  const videoBuffer = fs.readFileSync(outputPath);

  return {
    json: {
      videoGenerated: true,
      duration: totalDuration,
      numImages: numImages
    },
    binary: {
      video: {
        data: videoBuffer.toString('base64'),
        mimeType: 'video/mp4',
        fileName: 'youtube_short.mp4'
      }
    }
  };
} finally {
  // Cleanup temp files
  try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch (e) {}
}

const scriptData = $('Parse Script JSON').first().json;

const title = (scriptData.title || 'Tech News Today') + ' #Shorts';
const description = (scriptData.description || '') + '\n\n#Shorts #TechNews #AI #Technology';
const tags = scriptData.tags || ['tech', 'news', 'AI', 'shorts'];

const finalTitle = title.length > 100 ? title.substring(0, 97) + '...' : title;

return {
  json: {
    title: finalTitle,
    description: description,
    tags: tags,
    categoryId: '28',
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false
  },
  binary: $input.first().binary
};

const videoData = $input.first().json;
const videoId = videoData.uploadId || videoData.id || videoData.videoId || 'unknown';
const videoUrl = `https://youtube.com/shorts/${videoId}`;

return {
  json: {
    success: true,
    message: `YouTube Short published successfully!`,
    videoUrl: videoUrl,
    videoId: videoId,
    title: videoData.snippet?.title || videoData.title || '',
    uploadTime: new Date().toISOString()
  }
};
